function executeSearch()
{  
      //alert("oooooo!");
    document.trssearchform.method = 'post'; 
    document.trssearchform.submit();
}
function cancelSearch()
{  
    //去掉链接参数中的searchType，searchValue参数
    var oParams = top.location.search.toQueryParams() || {};
    delete oParams["searchType"];
    delete oParams["searchValue"];
    var sUrl = top.location.href;
    var match = /^([^\?]+).*$/.exec(sUrl);
    if(match){
        sUrl = match[1];
        var sParams = $toQueryStr(oParams);
        if(sParams && sParams.length > 0){
            sUrl += "?" + sParams
        }
    }
    window.top.location.href = sUrl;
}

/**
*由相对路径获取绝对路径
*/
function getCanonicalPath(_sPath){
    //处理掉./的情况
    _sPath = _sPath.replace(/\/\.\/+/g, "/");
    if(_sPath.indexOf('../') == -1){
        return _sPath;
    }
    var protocol = "";
    var colonIndex = _sPath.indexOf("://");
    if(colonIndex >= 0){
        protocol = _sPath.substring(0, colonIndex+3);
        _sPath = _sPath.substring(colonIndex+3);
    }
    var aPath = _sPath.split("/");
    for(var i = 0; i < aPath.length; i++){
        if(aPath[i] && aPath[i] == ".."){
            delete aPath[i];
            //删除前面的一个路径
            for(var j = i - 1; j >= 0; j--){
                if(aPath[j]){
                    delete aPath[j];
                    break;
                }
            }
        }
    }
    var result = "";
    for(var i = 0; i < aPath.length; i++){
        if(aPath[i]){
            result += aPath[i] + "/";
        }
    }
    return protocol + result;
}

/**
*获取站点的绝对地址
*/
function getPubURL(){
    var sWebSiteURL = '../../';
    var sCurrPageURL = window.location.href.replace(/\/[^\/]*$/g, "/");
    return getCanonicalPath(sCurrPageURL + sWebSiteURL);
}
$('pubURL').value = getPubURL();
